const formatPrice = (price) => {
  const numericPrice = typeof price === "number" ? price : parseFloat(price);
  if (isNaN(numericPrice)) {
    return "$0.00";
  }
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(numericPrice);
};

export default formatPrice;

import { createContext, useContext, useEffect, useState } from "react";
import { products } from "../data/products";

const CartContext = createContext();

const CART_STORAGE_KEY = "shopeasy_cart";

const getStoredCart = () => {
  try {
    const stored = sessionStorage.getItem(CART_STORAGE_KEY);
    return stored ? JSON.parse(stored) : [];
  } catch (error) {
    return [];
  }
};

const storeCart = (cartItems) => {
  try {
    sessionStorage.setItem(CART_STORAGE_KEY, JSON.stringify(cartItems));
  } catch (error) {
    // Silently fail if storage is not available
  }
};

const CartProvider = ({ children }) => {
  const [cartItems, setCartItems] = useState([]);

  useEffect(() => {
    setCartItems(getStoredCart());
  }, []);

  useEffect(() => {
    storeCart(cartItems);
  }, [cartItems]);

  const addToCart = (productId, quantity = 1) => {
    const product = products.find((p) => p.id === productId);
    if (!product) return;

    setCartItems((prevItems) => {
      const existingItem = prevItems.find((item) => item.productId === productId);
      if (existingItem) {
        const newQuantity = Math.min(
          existingItem.quantity + quantity,
          product.stock
        );
        return prevItems.map((item) =>
          item.productId === productId
            ? { ...item, quantity: newQuantity }
            : item
        );
      }
      return [...prevItems, { productId, quantity, priceAtAdd: product.price }];
    });
  };

  const removeFromCart = (productId) => {
    setCartItems((prevItems) =>
      prevItems.filter((item) => item.productId !== productId)
    );
  };

  const updateQuantity = (productId, quantity) => {
    const product = products.find((p) => p.id === productId);
    if (!product) return;

    const validQuantity = Math.max(1, Math.min(quantity, product.stock));

    setCartItems((prevItems) =>
      prevItems.map((item) =>
        item.productId === productId
          ? { ...item, quantity: validQuantity }
          : item
      )
    );
  };

  const clearCart = () => {
    setCartItems([]);
  };

  const getCartTotal = () => {
    return cartItems.reduce((total, item) => {
      return total + item.priceAtAdd * item.quantity;
    }, 0);
  };

  const getCartItemCount = () => {
    return cartItems.reduce((count, item) => count + item.quantity, 0);
  };

  const getItemByProductId = (productId) => {
    return cartItems.find((item) => item.productId === productId);
  };

  const value = {
    cartItems,
    addToCart,
    removeFromCart,
    updateQuantity,
    clearCart,
    getCartTotal,
    getCartItemCount,
    getItemByProductId,
  };

  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;
};

const useCart = () => {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error("useCart must be used within a CartProvider");
  }
  return context;
};

export { CartProvider, useCart };
export default CartContext;

import { TextInput, ActionIcon } from "@mantine/core";
import { IconSearch, IconX } from "@tabler/icons-react";
import { useInputState } from "@mantine/hooks";

const SearchBar = ({ onSearch, initialValue = "" }) => {
  const [value, setValue] = useInputState(initialValue);

  const handleSubmit = (event) => {
    event.preventDefault();
    if (onSearch) {
      onSearch(value);
    }
  };

  const handleClear = () => {
    setValue("");
    if (onSearch) {
      onSearch("");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ width: "100%" }}>
      <TextInput
        placeholder="Search products..."
        value={value}
        onChange={setValue}
        rightSection={
          value ? (
            <ActionIcon
              variant="subtle"
              color="gray"
              size="sm"
              onClick={handleClear}
              aria-label="Clear search"
              type="button"
            >
              <IconX size={16} />
            </ActionIcon>
          ) : (
            <IconSearch size={18} style={{ color: "var(--mantine-color-gray-5)" }} />
          )
        }
        styles={{
          input: {
            width: "100%",
            fontSize: "var(--mantine-font-size-sm)",
          },
        }}
      />
    </form>
  );
};

export default SearchBar;

import { Group, ActionIcon, NumberInput, rem } from "@mantine/core";
import { IconMinus, IconPlus } from "@tabler/icons-react";

const QuantitySelector = ({ value, onChange, min = 1, max = 99, disabled = false }) => {
  const handleIncrement = () => {
    if (value < max && onChange) {
      onChange(value + 1);
    }
  };

  const handleDecrement = () => {
    if (value > min && onChange) {
      onChange(value - 1);
    }
  };

  return (
    <Group spacing="xs" align="center">
      <ActionIcon
        variant="outline"
        color="gray"
        size="sm"
        onClick={handleDecrement}
        disabled={disabled || value <= min}
        aria-label="Decrease quantity"
      >
        <IconMinus size={rem(14)} />
      </ActionIcon>
      <NumberInput
        value={value}
        onChange={(val) => {
          const numValue = typeof val === "number" ? val : parseInt(val, 10) || min;
          const clampedValue = Math.max(min, Math.min(numValue, max));
          if (onChange) {
            onChange(clampedValue);
          }
        }}
        min={min}
        max={max}
        disabled={disabled}
        hideControls
        styles={{
          input: {
            width: rem(50),
            textAlign: "center",
            fontSize: "var(--mantine-font-size-sm)",
          },
        }}
        aria-label="Quantity"
      />
      <ActionIcon
        variant="outline"
        color="gray"
        size="sm"
        onClick={handleIncrement}
        disabled={disabled || value >= max}
        aria-label="Increase quantity"
      >
        <IconPlus size={rem(14)} />
      </ActionIcon>
    </Group>
  );
};

export default QuantitySelector;

import { Group, Chip, Slider, Text, Box, Button } from "@mantine/core";
import { useState } from "react";

const FilterPanel = ({ categories, selectedCategory, onCategoryChange, priceRange, onPriceChange, onClearFilters }) => {
  const [priceRangeValue, setPriceRangeValue] = useState(priceRange || [0, 300]);

  const handlePriceChange = (values) => {
    setPriceRangeValue(values);
    if (onPriceChange) {
      onPriceChange(values);
    }
  };

  const handleClear = () => {
    setPriceRangeValue([0, 300]);
    if (onClearFilters) {
      onClearFilters();
    }
  };

  const safeCategories = Array.isArray(categories) ? categories : [];

  return (
    <Box>
      <Box mb="md">
        <Text size="sm" weight={500} mb="xs" c="dimmed">
          Categories
        </Text>
        <Chip.Group
          value={selectedCategory}
          onChange={onCategoryChange}
          multiple={false}
        >
          <Group spacing="xs" position="apart">
            {safeCategories.map((category) => (
              <Chip
                key={category}
                value={category}
                variant="filled"
                size="sm"
                radius="sm"
              >
                {category}
              </Chip>
            ))}
          </Group>
        </Chip.Group>
      </Box>

      <Box mb="md">
        <Text size="sm" weight={500} mb="xs" c="dimmed">
          Price Range
        </Text>
        <Slider
          min={0}
          max={300}
          step={10}
          value={priceRangeValue}
          onChange={handlePriceChange}
          label={(value) => `$${value}`}
          styles={{
            track: { marginTop: rem(10) },
          }}
        />
        <Group position="apart" mt="xs">
          <Text size="xs" c="dimmed">
            ${priceRangeValue[0]}
          </Text>
          <Text size="xs" c="dimmed">
            ${priceRangeValue[1]}
          </Text>
        </Group>
      </Box>

      <Button
        variant="subtle"
        color="gray"
        size="sm"
        onClick={handleClear}
        fullWidth
        mt="sm"
      >
        Clear Filters
      </Button>
    </Box>
  );
};

export default FilterPanel;

