import FilterPanel from "../common/FilterPanel";

const FilterBarSection = ({
  categories,
  selectedCategory,
  onCategoryChange,
  priceRange,
  onPriceChange,
  onClearFilters,
}) => {
  const [opened, { open, close }] = useDisclosure(false);
  const theme = useMantineTheme();
  const isMobile = useMediaQuery(`(max-width: ${theme.breakpoints.sm})`);

  const filterContent = (
    <FilterPanel
      categories={categories}
      selectedCategory={selectedCategory}
      onCategoryChange={onCategoryChange}
      priceRange={priceRange}
      onPriceChange={onPriceChange}
      onClearFilters={onClearFilters}
    />
  );

  if (isMobile) {
    return (
      <>
        <Box
          style={{
            position: "sticky",
            top: rem(60),
            backgroundColor: "var(--mantine-color-body)",
            zIndex: 10,
            padding: `${rem(12)} ${rem(16)}`,
            borderBottom: "1px solid var(--mantine-color-gray-3)",
          }}
        >
          <Group position="apart">
            <Button
              leftIcon={<IconFilter size={16} />}
              variant="light"
              color="gray"
              size="sm"
              onClick={open}
            >
              Filters
            </Button>
            {selectedCategory && selectedCategory !== "All" && (
              <Button
                variant="subtle"
                color="gray"
                size="sm"
                onClick={onClearFilters}
              >
                Clear
              </Button>
            )}
          </Group>
        </Box>

        <Drawer
          opened={opened}
          onClose={close}
          title="Filter Products"
          padding="md"
          size="sm"
          position="right"
        >
          {filterContent}
        </Drawer>
      </>
    );
  }

  return (
    <Box
      style={{
        padding: `${rem(16)} 0`,
        borderBottom: "1px solid var(--mantine-color-gray-3)",
      }}
    >
      <Group position="left" spacing="lg" align="flex-end">
        {filterContent}
      </Group>
    </Box>
  );
};

export default FilterBarSection;

import { SimpleGrid, Text, Center, Box, Alert } from "@mantine/core";
import { IconInfoCircle } from "@tabler/icons-react";
import ProductCard from "../common/ProductCard";

const ProductGridSection = ({ products, loading = false }) => {
  const safeProducts = Array.isArray(products) ? products : [];

  if (loading) {
    return (
      <SimpleGrid cols={4} spacing="lg" breakpoints={[
        { minWidth: "sm", cols: 2 },
        { minWidth: "md", cols: 3 },
        { minWidth: "lg", cols: 4 },
      ]}>
        {Array.from({ length: 8 }).map((_, index) => (
          <ProductCard key={index} loading={true} />
        ))}
      </SimpleGrid>
    );
  }

  if (safeProducts.length === 0) {
    return (
      <Center style={{ minHeight: 300 }}>
        <Alert
          icon={<IconInfoCircle size={20} />}
          title="No products found"
          color="gray"
          variant="light"
        >
          Try adjusting your search or filter criteria to find what you're looking for.
        </Alert>
      </Center>
    );
  }

  return (
    <Box pt="lg">
      <SimpleGrid
        cols={1}
        spacing="lg"
        breakpoints={[
          { minWidth: "sm", cols: 2 },
          { minWidth: "md", cols: 3 },
          { minWidth: "lg", cols: 4 },
        ]}
      >
        {safeProducts.map((product) => (
          <ProductCard key={product.id} product={product} />
        ))}
      </SimpleGrid>
    </Box>
  );
};

export default ProductGridSection;

import { Image, Group, Box, rem } from "@mantine/core";
import { useState } from "react";

const ProductGallery = ({ product }) => {
  const [selectedImage, setSelectedImage] = useState(0);

  if (!product) {
    return null;
  }

  const { name, image } = product;

  // Generate additional thumbnail images based on the main image
  const thumbnails = [
    image,
    image.replace("/400/400", "/401/401"),
    image.replace("/400/400", "/402/402"),
    image.replace("/400/400", "/403/403"),
  ];

  return (
    <Box>
      <Box
        style={{
          border: "1px solid var(--mantine-color-gray-3)",
          borderRadius: rem(12),
          overflow: "hidden",
          marginBottom: rem(16),
        }}
      >
        <Image
          src={thumbnails[selectedImage]}
          alt={`${name} - view ${selectedImage + 1}`}
          height={400}
          style={{ objectFit: "cover", width: "100%" }}
        />
      </Box>

